class Solution:
    def exclusiveTime(self, n: int, logs: list[str]) -> list[int]:
        ans = [0] * n
        stack = []
        prev = None
        for log in logs:
            fid_s, typ, t_s = log.split(':')
            fid, t = int(fid_s), int(t_s)
            if prev is not None and stack:
                end = t + 1 if typ == 'end' else t
                for _ in range(prev, end):
                    ans[stack[-1]] += 1
            if typ == 'start':
                stack.append(fid)
                prev = t
            else:
                stack.pop()
                prev = t + 1
        return ans

