class Solution:
    def exclusiveTime(self, n: int, logs: list[str]) -> list[int]:
        ans = [0] * n
        stack = []
        prev = 0
        for log in logs:
            fid_s, typ, t_s = log.split(':')
            fid, t = int(fid_s), int(t_s)
            if typ == 'start':
                if stack:
                    ans[stack[-1]] += t - prev
                stack.append(fid)
                prev = t
            else:
                ans[stack.pop()] += t - prev + 1
