class Solution:
    def exclusiveTime(self, n: int, logs: list[str]) -> list[int]:
        ans = [0] * n
        stack = []
        prev = 0
        for log in logs:
            a = log.find(':')
            b = log.find(':', a + 1)
            fid = int(log[:a])
            typ = log[a + 1:b]
            t = int(log[b + 1:])
            if typ == 'start':
                if stack:
                    ans[stack[-1]] += t - prev
                stack.append(fid)
                prev = t
            else:
                ans[stack.pop()] += t - prev + 1
                prev = t + 1
        return ans

